    if damage_dealt < 25:
        band = "light"
    elif damage_dealt < 50:
        band = "heavy"
    else:
        band = "devastating"

    if combo["hit_count"] >= 4 or terminal == "kill":
        event = {
            "game": current_game,
            "attacker": attacker_name,
            "victim_stock_before": combo["victim_stock_before"],
            "hit_count": combo["hit_count"],
            "damage_band": band,
            "terminal": terminal
        }
        events_ledger.append(event)
        print(f"Recorded Combo: Game {current_game}, {attacker_name} -> {victim_name}, hits={combo['hit_count']}, dmg={damage_dealt}%, terminal={terminal}")

    combo["active"] = False

