def get_outline_mask(img):
    B = img[:, :, 0]
    G = img[:, :, 1]
    R = img[:, :, 2]
    bright = R > 110
    black = (R < 45) & (G < 45) & (B < 45)
    kernel = np.ones((7, 7), dtype=np.uint8)
    dilated_black = cv2.dilate(black.astype(np.uint8), kernel)
    return bright & (dilated_black > 0)

def keep_largest_component(mask):
    num_labels, labels, stats, centroids = cv2.connectedComponentsWithStats(mask.astype(np.uint8))
    if num_labels <= 1:
        return mask
    max_label = 1 + np.argmax(stats[1:, cv2.CC_STAT_AREA])
    return labels == max_label

def find_best_shift_and_iou(mask1, mask2):
    h, w = mask1.shape
    best_iou = 0.0
    best_dx, best_dy = 0, 0
    for dy in range(-6, 7):
        for dx in range(-10, 11):
            shifted = np.zeros_like(mask2)
            y1_src = max(0, -dy)
            y2_src = min(h, h - dy)
            x1_src = max(0, -dx)
            x2_src = min(w, w - dx)

            y1_dst = max(0, dy)
            y2_dst = min(h, h + dy)
            x1_dst = max(0, dx)
            x2_dst = min(w, w + dx)

            if y2_src > y1_src and x2_src > x1_src:
                shifted[y1_dst:y2_dst, x1_dst:x2_dst] = mask2[y1_src:y2_src, x1_src:x2_src]

            intersection = np.logical_and(mask1, shifted).sum()
            union = np.logical_or(mask1, shifted).sum()
            iou = intersection / union if union > 0 else 0
            if iou > best_iou:
                best_iou = iou
                best_dx = dx
                best_dy = dy
    return best_iou, best_dx, best_dy

def compute_iou_at_shift(mask1, mask2, dx, dy):
    h, w = mask1.shape
    shifted = np.zeros_like(mask2)
    y1_src = max(0, -dy)
    y2_src = min(h, h - dy)
    x1_src = max(0, -dx)
    x2_src = min(w, w - dx)

    y1_dst = max(0, dy)
    y2_dst = min(h, h + dy)
    x1_dst = max(0, dx)
    x2_dst = min(w, w + dx)

    if y2_src > y1_src and x2_src > x1_src:
        shifted[y1_dst:y2_dst, x1_dst:x2_dst] = mask2[y1_src:y2_src, x1_src:x2_src]

    intersection = np.logical_and(mask1, shifted).sum()
    union = np.logical_or(mask1, shifted).sum()
    return intersection / union if union > 0 else 0

